import java.util.*;

public class BacktrackingBasics {

    // ============ 1. 全排列 ============
    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        backtrackPermute(nums, new boolean[nums.length], new ArrayList<>(), result);
        return result;
    }

    private void backtrackPermute(int[] nums, boolean[] used,
                                  List<Integer> path, List<List<Integer>> result) {
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path)); // 收集时必须复制
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;  // 已选过，跳过
            used[i] = true;
            path.add(nums[i]);
            backtrackPermute(nums, used, path, result);
            path.remove(path.size() - 1); // 撤销选择
            used[i] = false;              // 恢复标记
        }
    }

    // ============ 2. 组合 C(n,k) ============
    public List<List<Integer>> combine(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        backtrackCombine(n, k, 1, new ArrayList<>(), result);
        return result;
    }

    private void backtrackCombine(int n, int k, int start,
                                  List<Integer> path, List<List<Integer>> result) {
        if (path.size() == k) {
            result.add(new ArrayList<>(path));
            return;
        }
        // 剪枝：剩余元素不够凑满 k 个时提前返回
        for (int i = start; i <= n - (k - path.size()) + 1; i++) {
            path.add(i);
            backtrackCombine(n, k, i + 1, path, result); // i+1 保证不重复选
            path.remove(path.size() - 1);
        }
    }

    // ============ 3. 子集 ============
    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        backtrackSubsets(nums, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrackSubsets(int[] nums, int start,
                                  List<Integer> path, List<List<Integer>> result) {
        result.add(new ArrayList<>(path)); // 每个节点都是合法子集
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            backtrackSubsets(nums, i + 1, path, result);
            path.remove(path.size() - 1);
        }
    }

    // ============ 4. 含重复元素的子集（排序+同层跳过） ============
    public List<List<Integer>> subsetsWithDup(int[] nums) {
        Arrays.sort(nums); // 排序是去重的前提
        List<List<Integer>> result = new ArrayList<>();
        backtrackSubsetsDup(nums, 0, new ArrayList<>(), result);
        return result;
    }

    private void backtrackSubsetsDup(int[] nums, int start,
                                     List<Integer> path, List<List<Integer>> result) {
        result.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            if (i > start && nums[i] == nums[i - 1]) continue; // 同层跳过重复
            path.add(nums[i]);
            backtrackSubsetsDup(nums, i + 1, path, result);
            path.remove(path.size() - 1);
        }
    }

    // ============ 5. N 皇后 ============
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        backtrackNQueens(board, 0, result);
        return result;
    }

    private void backtrackNQueens(char[][] board, int row, List<List<String>> result) {
        int n = board.length;
        if (row == n) {
            List<String> solution = new ArrayList<>();
            for (char[] r : board) solution.add(new String(r));
            result.add(solution);
            return;
        }
        for (int col = 0; col < n; col++) {
            if (!isValid(board, row, col)) continue; // 可行性剪枝
            board[row][col] = 'Q';
            backtrackNQueens(board, row + 1, result);
            board[row][col] = '.'; // 撤销
        }
    }

    private boolean isValid(char[][] board, int row, int col) {
        int n = board.length;
        for (int i = 0; i < row; i++) {  // 检查列
            if (board[i][col] == 'Q') return false;
        }
        for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) { // 左上对角线
            if (board[i][j] == 'Q') return false;
        }
        for (int i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) { // 右上对角线
            if (board[i][j] == 'Q') return false;
        }
        return true;
    }

    // ============ 测试 ============
    public static void main(String[] args) {
        BacktrackingBasics bt = new BacktrackingBasics();

        System.out.println("Permutations of [1,2,3]:");
        System.out.println(bt.permute(new int[]{1, 2, 3}));

        System.out.println("\nCombinations C(4,2):");
        System.out.println(bt.combine(4, 2));

        System.out.println("\nSubsets of [1,2,3]:");
        System.out.println(bt.subsets(new int[]{1, 2, 3}));

        System.out.println("\nSubsets with dup of [1,2,2]:");
        System.out.println(bt.subsetsWithDup(new int[]{1, 2, 2}));

        System.out.println("\n4-Queens solutions:");
        List<List<String>> queens = bt.solveNQueens(4);
        for (List<String> sol : queens) {
            for (String row : sol) System.out.println(row);
            System.out.println();
        }
    }
}
